CREATE TABLE taxonomy_sync_runs (id BIGSERIAL PRIMARY KEY, collection_domain_run_id BIGINT NOT NULL REFERENCES collection_domain_runs(id) ON DELETE CASCADE, taxonomy_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'COMPLETED', observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT taxonomy_sync_runs_status_check CHECK (status IN ('COMPLETED','FAILED')), CONSTRAINT taxonomy_sync_runs_hash_check CHECK(taxonomy_hash ~ '^[0-9a-f]{64}$'));
CREATE TABLE provider_categories (id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'OZON', provider_category_id BIGINT NOT NULL, first_observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), last_observed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT provider_categories_provider_check CHECK (provider = 'OZON'), CONSTRAINT provider_categories_id_check CHECK(provider_category_id > 0), CONSTRAINT provider_categories_identity_unique UNIQUE(provider,provider_category_id));
CREATE TABLE provider_category_versions (id BIGSERIAL PRIMARY KEY, provider_category_id BIGINT NOT NULL REFERENCES provider_categories(id) ON DELETE CASCADE, parent_provider_category_id BIGINT NULL REFERENCES provider_categories(id) ON DELETE RESTRICT, name TEXT NOT NULL, disabled BOOLEAN NOT NULL, is_leaf BOOLEAN NOT NULL, taxonomy_state TEXT NOT NULL, taxonomy_sync_run_id BIGINT NOT NULL REFERENCES taxonomy_sync_runs(id) ON DELETE RESTRICT, observed_at TIMESTAMPTZ NOT NULL, normalized_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT provider_category_versions_state_check CHECK(taxonomy_state IN ('ACTIVE','DISABLED','UNOBSERVED')));
CREATE INDEX idx_provider_category_versions_category_observed ON provider_category_versions(provider_category_id, observed_at DESC);
CREATE TABLE provider_product_types (id BIGSERIAL PRIMARY KEY, provider TEXT NOT NULL DEFAULT 'OZON', provider_category_id BIGINT NOT NULL REFERENCES provider_categories(id) ON DELETE RESTRICT, provider_type_id BIGINT NOT NULL, first_observed_at TIMESTAMPTZ NOT NULL, last_observed_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT provider_product_types_provider_check CHECK(provider='OZON'), CONSTRAINT provider_product_types_id_check CHECK(provider_type_id > 0), CONSTRAINT provider_product_types_identity_unique UNIQUE(provider,provider_category_id,provider_type_id));
CREATE TABLE provider_product_type_versions (id BIGSERIAL PRIMARY KEY, provider_product_type_id BIGINT NOT NULL REFERENCES provider_product_types(id) ON DELETE CASCADE, provider_category_id BIGINT NOT NULL REFERENCES provider_categories(id) ON DELETE RESTRICT, name TEXT NOT NULL, disabled BOOLEAN NOT NULL, taxonomy_state TEXT NOT NULL, taxonomy_sync_run_id BIGINT NOT NULL REFERENCES taxonomy_sync_runs(id) ON DELETE RESTRICT, observed_at TIMESTAMPTZ NOT NULL, normalized_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT provider_product_type_versions_state_check CHECK(taxonomy_state IN ('ACTIVE','DISABLED','UNOBSERVED')));
CREATE INDEX idx_provider_product_type_versions_type_observed ON provider_product_type_versions(provider_product_type_id, observed_at DESC);
CREATE TABLE canonical_skus (id BIGSERIAL PRIMARY KEY, seller_account_id BIGINT NOT NULL REFERENCES seller_accounts(id) ON DELETE CASCADE, ozon_sku BIGINT NOT NULL, first_observed_at TIMESTAMPTZ NOT NULL, last_observed_at TIMESTAMPTZ NOT NULL, catalog_state TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT canonical_skus_identity_unique UNIQUE(seller_account_id,ozon_sku), CONSTRAINT canonical_skus_ozon_sku_check CHECK(ozon_sku > 0), CONSTRAINT canonical_skus_state_check CHECK(catalog_state IN ('ACTIVE','ARCHIVED','UNOBSERVED','UNKNOWN')));
CREATE INDEX idx_canonical_skus_seller_state ON canonical_skus(seller_account_id,catalog_state);
CREATE TABLE canonical_sku_versions (id BIGSERIAL PRIMARY KEY, canonical_sku_id BIGINT NOT NULL REFERENCES canonical_skus(id) ON DELETE CASCADE, provider_product_id BIGINT NULL, offer_id TEXT NULL, name TEXT NULL, provider_status TEXT NULL, catalog_state TEXT NOT NULL, normalized_hash TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, collection_domain_run_id BIGINT NOT NULL REFERENCES collection_domain_runs(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT canonical_sku_versions_state_check CHECK(catalog_state IN ('ACTIVE','ARCHIVED','UNOBSERVED','UNKNOWN')));
CREATE INDEX idx_canonical_sku_versions_sku_observed ON canonical_sku_versions(canonical_sku_id,observed_at DESC);
CREATE TABLE canonical_sku_content_snapshots (id BIGSERIAL PRIMARY KEY, canonical_sku_id BIGINT NOT NULL REFERENCES canonical_skus(id) ON DELETE CASCADE, primary_image_url TEXT NULL, image_urls JSONB NULL, normalized_hash TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, collection_domain_run_id BIGINT NOT NULL REFERENCES collection_domain_runs(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE canonical_sku_relations (id BIGSERIAL PRIMARY KEY, seller_account_id BIGINT NOT NULL REFERENCES seller_accounts(id) ON DELETE CASCADE, canonical_sku_id BIGINT NOT NULL REFERENCES canonical_skus(id) ON DELETE CASCADE, related_canonical_sku_id BIGINT NOT NULL REFERENCES canonical_skus(id) ON DELETE CASCADE, relation_type TEXT NOT NULL, observed_at TIMESTAMPTZ NOT NULL, collection_domain_run_id BIGINT NOT NULL REFERENCES collection_domain_runs(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT canonical_sku_relations_distinct_check CHECK(canonical_sku_id <> related_canonical_sku_id), CONSTRAINT canonical_sku_relations_observation_unique UNIQUE(seller_account_id,canonical_sku_id,related_canonical_sku_id,relation_type,observed_at));
CREATE TABLE seller_categories (id BIGSERIAL PRIMARY KEY, seller_account_id BIGINT NOT NULL REFERENCES seller_accounts(id) ON DELETE CASCADE, provider_category_id BIGINT NOT NULL REFERENCES provider_categories(id) ON DELETE RESTRICT, first_observed_at TIMESTAMPTZ NOT NULL, last_observed_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT seller_categories_identity_unique UNIQUE(seller_account_id,provider_category_id));
CREATE TABLE sku_category_assignments (id BIGSERIAL PRIMARY KEY, canonical_sku_id BIGINT NOT NULL REFERENCES canonical_skus(id) ON DELETE CASCADE, seller_category_id BIGINT NULL REFERENCES seller_categories(id) ON DELETE RESTRICT, raw_provider_category_id BIGINT NULL, provider_product_type_id BIGINT NULL REFERENCES provider_product_types(id) ON DELETE RESTRICT, raw_provider_product_type_id BIGINT NULL, mapping_status TEXT NOT NULL, observed_from TIMESTAMPTZ NOT NULL, observed_to TIMESTAMPTZ NULL, collection_domain_run_id BIGINT NOT NULL REFERENCES collection_domain_runs(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CONSTRAINT sku_category_assignments_status_check CHECK(mapping_status IN ('MAPPED','UNMAPPED','UNKNOWN')));
CREATE UNIQUE INDEX uq_sku_category_assignments_current ON sku_category_assignments(canonical_sku_id) WHERE observed_to IS NULL;
CREATE OR REPLACE FUNCTION enforce_catalog_seller_match() RETURNS TRIGGER AS $$ BEGIN
IF TG_TABLE_NAME='taxonomy_sync_runs' THEN
  IF NOT EXISTS(SELECT 1 FROM collection_domain_runs dr WHERE dr.id=NEW.collection_domain_run_id AND dr.domain='TAXONOMY') THEN RAISE EXCEPTION 'taxonomy sync must reference TAXONOMY domain run' USING ERRCODE='23514'; END IF;
ELSIF TG_TABLE_NAME='seller_categories' THEN
  IF NOT EXISTS(SELECT 1 FROM provider_category_versions v WHERE v.provider_category_id=NEW.provider_category_id ORDER BY v.observed_at DESC,v.id DESC LIMIT 1) THEN RAISE EXCEPTION 'seller category must reference a known provider category' USING ERRCODE='23514'; END IF;
  IF NOT (SELECT v.is_leaf AND v.taxonomy_state='ACTIVE' FROM provider_category_versions v WHERE v.provider_category_id=NEW.provider_category_id ORDER BY v.observed_at DESC,v.id DESC LIMIT 1) THEN RAISE EXCEPTION 'seller category must reference a current enabled leaf provider category' USING ERRCODE='23514'; END IF;
ELSIF TG_TABLE_NAME='canonical_sku_versions' THEN
  IF NOT EXISTS(SELECT 1 FROM canonical_skus cs JOIN collection_domain_runs dr ON dr.id=NEW.collection_domain_run_id WHERE cs.id=NEW.canonical_sku_id AND cs.seller_account_id=dr.seller_account_id AND dr.domain='CATALOG') THEN RAISE EXCEPTION 'SKU version domain run seller/domain mismatch' USING ERRCODE='23514'; END IF;
ELSIF TG_TABLE_NAME='canonical_sku_content_snapshots' THEN
  IF NOT EXISTS(SELECT 1 FROM canonical_skus cs JOIN collection_domain_runs dr ON dr.id=NEW.collection_domain_run_id WHERE cs.id=NEW.canonical_sku_id AND cs.seller_account_id=dr.seller_account_id AND dr.domain='CATALOG') THEN RAISE EXCEPTION 'SKU content domain run seller/domain mismatch' USING ERRCODE='23514'; END IF;
ELSIF TG_TABLE_NAME='canonical_sku_relations' THEN
  IF NOT EXISTS(SELECT 1 FROM canonical_skus a JOIN canonical_skus b ON b.id=NEW.related_canonical_sku_id JOIN collection_domain_runs dr ON dr.id=NEW.collection_domain_run_id WHERE a.id=NEW.canonical_sku_id AND a.seller_account_id=NEW.seller_account_id AND b.seller_account_id=NEW.seller_account_id AND dr.seller_account_id=NEW.seller_account_id AND dr.domain='CATALOG') THEN RAISE EXCEPTION 'SKU relation seller/domain mismatch' USING ERRCODE='23514'; END IF;
ELSIF TG_TABLE_NAME='sku_category_assignments' THEN
  IF NOT EXISTS(SELECT 1 FROM canonical_skus cs JOIN collection_domain_runs dr ON dr.id=NEW.collection_domain_run_id LEFT JOIN seller_categories sc ON sc.id=NEW.seller_category_id WHERE cs.id=NEW.canonical_sku_id AND cs.seller_account_id=dr.seller_account_id AND dr.domain='CATALOG' AND (NEW.seller_category_id IS NULL OR sc.seller_account_id=cs.seller_account_id)) THEN RAISE EXCEPTION 'assignment seller/domain mismatch' USING ERRCODE='23514'; END IF;
END IF;
RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER seller_categories_leaf_trigger BEFORE INSERT OR UPDATE OF provider_category_id ON seller_categories FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
CREATE TRIGGER taxonomy_sync_runs_domain_trigger BEFORE INSERT OR UPDATE OF collection_domain_run_id ON taxonomy_sync_runs FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
CREATE TRIGGER sku_category_assignments_seller_trigger BEFORE INSERT OR UPDATE OF canonical_sku_id,seller_category_id,collection_domain_run_id ON sku_category_assignments FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
CREATE TRIGGER canonical_sku_versions_seller_trigger BEFORE INSERT OR UPDATE OF canonical_sku_id,collection_domain_run_id ON canonical_sku_versions FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
CREATE TRIGGER canonical_sku_content_snapshots_seller_trigger BEFORE INSERT OR UPDATE OF canonical_sku_id,collection_domain_run_id ON canonical_sku_content_snapshots FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
CREATE TRIGGER canonical_sku_relations_seller_trigger BEFORE INSERT OR UPDATE OF seller_account_id,canonical_sku_id,related_canonical_sku_id,collection_domain_run_id ON canonical_sku_relations FOR EACH ROW EXECUTE FUNCTION enforce_catalog_seller_match();
